SELECT id, practice_script->>'version' AS version, md5(practice_script::text) AS huella FROM public.nodes WHERE id IN ('4.11','5.1','5.3','5.8','5.12','5.13','5.14','5.15','7.3','7.4') ORDER BY id;
SELECT id, md5(concat_ws('|', paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default)) AS huella FROM public.reglas WHERE id IN ('close.aguanta_silencio','close.alternativa','close.asume_con_presion','close.asumir_venta','close.cierra_solo_incremento','close.descuento_de_panico','close.devuelve_el_volante','close.fishbbod','close.llena_el_silencio','close.mal_cierre','close.persigue','close.pide_aprobacion','close.reabre_pedido_base','close.sigue_presentando','close_with_action','flow.dos_no_seguidos','objection.regla_de_los_no','objections.regla_de_los_no') ORDER BY id;
SELECT max(version) AS version_cerebro, count(*) AS secciones, md5(string_agg(body, '#' ORDER BY order_index)) AS huella_cerebro FROM public.doctrina WHERE is_active;
SELECT node_id, card_order, md5(coalesce(title,'') || '|' || body) AS huella FROM public.node_cards WHERE (node_id, card_order) IN (('5.0',2),('5.11',2),('5.11',3)) ORDER BY node_id, card_order;
SELECT id, md5(short_description) AS huella FROM public.skills WHERE id IN ('objections.regla_no') ORDER BY id;
